#!/usr/bin/env node
'use strict';

// Normalise the extractor's XLSX workbook into a diffable JSON ledger.  This
// intentionally has no npm dependency: xlsx is a ZIP of XML files and the
// workbook generated by extract_top300_marcap.py stores values inline.

const fs = require('fs');
const path = require('path');
const cp = require('child_process');
const crypto = require('crypto');
const A = require('./lib/annual-top300-universe.js');

const ROOT = path.resolve(__dirname, '..', '..', '..');
const defaults = {
  input: path.join(ROOT, '한국_시가총액_상위300_2015-2025.xlsx'),
  out: path.join(ROOT, 'analysis-example/kr-market/strategies/annual-top300/universe-ledger.json'),
};
function arg(name, fallback) { const i = process.argv.indexOf(name); return i >= 0 ? process.argv[i + 1] : fallback; }
function sha(buf) { return crypto.createHash('sha256').update(buf).digest('hex'); }
function xmlUnescape(x) { return x.replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n))).replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>'); }
function unzip(file, entry) { return cp.execFileSync('unzip', ['-p', file, entry], { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 }); }
function cellText(cell) { const inline = cell.match(/<is>\s*<t[^>]*>([\s\S]*?)<\/t>\s*<\/is>/); if (inline) return xmlUnescape(inline[1]); const value = cell.match(/<v>([\s\S]*?)<\/v>/); return value ? xmlUnescape(value[1]) : ''; }
function column(ref) { return ref.match(/^[A-Z]+/)[0]; }
function worksheetRows(xml) {
  return [...xml.matchAll(/<row\b[^>]*>([\s\S]*?)<\/row>/g)].map(m => {
    const row = {}; for (const c of m[1].matchAll(/<c\b([^>]*)>([\s\S]*?)<\/c>/g)) { const ref = c[1].match(/\br="([A-Z]+\d+)"/)?.[1]; if (ref) row[column(ref)] = cellText(c[0]); } return row;
  });
}
function sheets(workbookXml) { return [...workbookXml.matchAll(/<sheet\b[^>]*\bname="([^"]+)"[^>]*\br:id="rId(\d+)"/g)].map(m => ({ name: xmlUnescape(m[1]), id: Number(m[2]) })); }

function main() {
  const input = arg('--input', defaults.input), out = arg('--out', defaults.out);
  if (!fs.existsSync(input)) throw new Error(`missing XLSX: ${input}; extract 2015–2025 first`);
  const raw = fs.readFileSync(input), workbook = unzip(input, 'xl/workbook.xml');
  const snapshots = [];
  for (const sheet of sheets(workbook)) {
    if (!/^\d{4}$/.test(sheet.name)) continue;
    const rankingYear = Number(sheet.name), rows = worksheetRows(unzip(input, `xl/worksheets/sheet${sheet.id}.xml`));
    const title = rows[0]?.A || '';
    const asOfDate = title.match(/(\d{4}-\d{2}-\d{2})/)?.[1];
    const rawRows = rows.slice(2).filter(r => r.A && r.B).map(r => ({ rank: Number(r.A), ticker: String(r.B).padStart(6, '0'), name: r.C, market: r.D, close: Number(r.E), marketCap: Number(r.F) * 100000000, stocks: Number(r.G) }));
    const snapshotHash = sha(Buffer.from(JSON.stringify(rawRows)));
    snapshots.push(A.normaliseSnapshot({ rankingYear, asOfDate, rawTop300Count: rawRows.length, sourceSha256: snapshotHash, constituents: rawRows }));
  }
  const payload = {
    schemaVersion: 1, generatedAt: new Date().toISOString(), source: { file: path.basename(input), sha256: sha(raw), provider: 'FinanceData/marcap via KRX' }, snapshots,
    notes: 'Snapshot t is used only for trading signals in t+1. marketCap is KRW; raw Top-300 count precedes common-share filtering.',
  };
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, JSON.stringify(payload, null, 2) + '\n');
  console.log(JSON.stringify({ out, years: snapshots.map(x => ({ year: x.rankingYear, asOfDate: x.asOfDate, raw: x.rawTop300Count, common: x.commonShareCount })) }, null, 2));
}
if (require.main === module) main();
